AP=ref('Society for Endocrinology: Emergency Management of Pituitary Apoplexy','https://pmc.ncbi.nlm.nih.gov/articles/PMC5314810/')
CU=ref('Pituitary Society: Cushing Disease Guideline Update, 2021','https://pmc.ncbi.nlm.nih.gov/articles/PMC8743006/')
